import{_ as n,C as a,o as r,c as E,E as d,a1 as e,b as h,w as o,a as s,a2 as A}from"./chunks/framework.NjEjlYNI.js";const m=JSON.parse('{"title":"公司选择","description":"资深前端公司选择指南 — 大厂/中厂/外企/创业公司评估维度、面试反向问题避坑","frontmatter":{"title":"公司选择","description":"资深前端公司选择指南 — 大厂/中厂/外企/创业公司评估维度、面试反向问题避坑","difficulty":"beginner","frequency":"medium"},"headers":[],"relativePath":"interview/company-selection.md","filePath":"interview/company-selection.md"}'),u={name:"interview/company-selection.md"};function B(b,t,c,q,f,p){const l=a("DifficultyBadge"),i=a("Mermaid");return r(),E("div",null,[d(l,{level:"beginner"}),t[1]||(t[1]=e('<h1 id="公司选择" tabindex="-1">公司选择 <a class="header-anchor" href="#公司选择" aria-label="Permalink to &quot;公司选择&quot;">​</a></h1><h2 id="一句话解释" tabindex="-1">一句话解释 <a class="header-anchor" href="#一句话解释" aria-label="Permalink to &quot;一句话解释&quot;">​</a></h2><p>选公司不是选&quot;名气最大的&quot;或&quot;薪资最高的&quot;，而是<strong>选一个能让你的职业生涯在 2-3 年后更有价值的平台</strong>——判断标准不是现在给你多少钱，而是这段经历能不能让你&quot;更值钱&quot;。</p><h2 id="决策框架" tabindex="-1">决策框架 <a class="header-anchor" href="#决策框架" aria-label="Permalink to &quot;决策框架&quot;">​</a></h2>',4)),(r(),h(A,null,{default:o(()=>[d(i,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E6%8B%BF%E5%88%B0%20Offer%5D%20--%3E%20B%7B%E5%85%AC%E5%8F%B8%E7%B1%BB%E5%9E%8B%3F%7D%0A%20%20%20%20%0A%20%20%20%20B%20--%3E%7C%E5%A4%A7%E5%8E%82%7C%20C%5B%E5%85%B3%E6%B3%A8%3A%20%E8%81%8C%E7%BA%A7%2F%E4%B8%9A%E5%8A%A1%E7%BA%BF%2F%E6%8A%80%E6%9C%AF%E6%B0%9B%E5%9B%B4%5D%0A%20%20%20%20B%20--%3E%7C%E4%B8%AD%E5%8E%82%7C%20D%5B%E5%85%B3%E6%B3%A8%3A%20%E4%B8%9A%E5%8A%A1%E5%A2%9E%E9%80%9F%2F%E6%8A%80%E6%9C%AF%E5%80%BA%2F%E6%99%8B%E5%8D%87%E7%A9%BA%E9%97%B4%5D%0A%20%20%20%20B%20--%3E%7C%E5%A4%96%E4%BC%81%7C%20E%5B%E5%85%B3%E6%B3%A8%3A%20WLB%2FGlobal%20%E5%BD%B1%E5%93%8D%2F%E6%8A%80%E6%9C%AF%E6%A0%88%5D%0A%20%20%20%20B%20--%3E%7C%E5%88%9B%E4%B8%9A%E5%85%AC%E5%8F%B8%7C%20F%5B%E5%85%B3%E6%B3%A8%3A%20%E8%9E%8D%E8%B5%84%E9%98%B6%E6%AE%B5%2F%E8%82%A1%E6%9D%83%E7%BB%93%E6%9E%84%2F%E4%B8%9A%E5%8A%A1%E7%A1%AE%E5%AE%9A%E6%80%A7%5D%0A%20%20%20%20%0A%20%20%20%20C%20--%3E%20G%5B%E7%BB%BC%E5%90%88%E8%AF%84%E4%BC%B0%5D%0A%20%20%20%20D%20--%3E%20G%0A%20%20%20%20E%20--%3E%20G%0A%20%20%20%20F%20--%3E%20G%0A%20%20%20%20%0A%20%20%20%20G%20--%3E%20H%7B%E8%96%AA%E8%B5%84%E5%B7%AE%E8%B7%9D%7D%0A%20%20%20%20H%20--%3E%7C%3E20%25%7C%20I%5B%E8%AE%A4%E7%9C%9F%E8%80%83%E8%99%91%E9%AB%98%E8%96%AA%20Offer%5D%0A%20%20%20%20H%20--%3E%7C%3C20%25%7C%20J%5B%E6%8C%89%E9%95%BF%E6%9C%9F%E4%BB%B7%E5%80%BC%E6%8E%92%E5%BA%8F%5D%0A%20%20%20%20%0A%20%20%20%20I%20--%3E%20K%5B%E5%8F%8D%E9%97%AE%E7%8E%AF%E8%8A%82%E6%94%B6%E9%9B%86%E4%BF%A1%E6%81%AF%5D%0A%20%20%20%20J%20--%3E%20K%0A%20%20%20%20%0A%20%20%20%20K%20--%3E%20L%5B%E6%9C%80%E7%BB%88%E5%86%B3%E7%AD%96%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<h2 id="深入理解" tabindex="-1">深入理解 <a class="header-anchor" href="#深入理解" aria-label="Permalink to &quot;深入理解&quot;">​</a></h2><h3 id="_1-公司分类与特点" tabindex="-1">1. 公司分类与特点 <a class="header-anchor" href="#_1-公司分类与特点" aria-label="Permalink to &quot;1. 公司分类与特点&quot;">​</a></h3><h4 id="大厂-bat-tmd-字节-拼多多等" tabindex="-1">大厂（BAT/TMD/字节/拼多多等） <a class="header-anchor" href="#大厂-bat-tmd-字节-拼多多等" aria-label="Permalink to &quot;大厂（BAT/TMD/字节/拼多多等）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>优势</th><th>劣势</th></tr></thead><tbody><tr><td>成熟的职级体系和晋升通道</td><td>业务线众多，边缘业务可能边缘人</td></tr><tr><td>规范的技术架构和工程文化</td><td>螺丝钉化风险</td></tr><tr><td>大平台背书，跳槽加分</td><td>内卷严重，部分厂 996</td></tr><tr><td>薪资有竞争力</td><td>层级多，决策流程长</td></tr><tr><td>学习资源丰富</td><td>技术栈可能老旧（如部分部门还在用内部框架）</td></tr></tbody></table><p><strong>适合人群：</strong> 想在体系化环境中做深做精，看重品牌背书</p><h4 id="中型公司-独角兽-500-2000-人" tabindex="-1">中型公司/独角兽（500-2000 人） <a class="header-anchor" href="#中型公司-独角兽-500-2000-人" aria-label="Permalink to &quot;中型公司/独角兽（500-2000 人）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>优势</th><th>劣势</th></tr></thead><tbody><tr><td>技术栈更前沿（敢于尝新）</td><td>工程规范可能不完善</td></tr><tr><td>个人影响力更明显</td><td>稳定性风险（B/C 轮最危险）</td></tr><tr><td>晋升更快</td><td>可能需要身兼多职</td></tr><tr><td>技术债少，可从 0 搭建体系</td><td>品牌背书不如大厂</td></tr></tbody></table><p><strong>适合人群：</strong> 想要更多 ownership，愿意承担一定风险换成长速度</p><h4 id="外企-microsoft-google-amazon-snap" tabindex="-1">外企（Microsoft/Google/Amazon/Snap） <a class="header-anchor" href="#外企-microsoft-google-amazon-snap" aria-label="Permalink to &quot;外企（Microsoft/Google/Amazon/Snap）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>优势</th><th>劣势</th></tr></thead><tbody><tr><td>WLB 好，远程灵活</td><td>中国团队边缘化风险</td></tr><tr><td>业务确定性高</td><td>技术栈不一定最新</td></tr><tr><td>Global 协作机会</td><td>晋升比国内大厂慢</td></tr><tr><td>薪资竞争力强（特别是 RSU）</td><td>文化差异，向上管理要求高</td></tr></tbody></table><p><strong>适合人群：</strong> 看重生活品质，希望有 Global 视野</p><h4 id="创业公司-a-c-轮" tabindex="-1">创业公司（A-C 轮） <a class="header-anchor" href="#创业公司-a-c-轮" aria-label="Permalink to &quot;创业公司（A-C 轮）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>优势</th><th>劣势</th></tr></thead><tbody><tr><td>成长速度最快，话语权大</td><td>生存风险（死亡率 &gt;90%）</td></tr><tr><td>期权潜在回报</td><td>薪资通常低于市场</td></tr><tr><td>从 0 到 1 的经验稀缺</td><td>可能需要降级 title</td></tr><tr><td>接触全栈/全流程</td><td>几乎没有培训体系</td></tr></tbody></table><p><strong>适合人群：</strong> 风险承受能力强，想体验从 0 到 1，有创业心态</p><h3 id="_2-评估维度框架" tabindex="-1">2. 评估维度框架 <a class="header-anchor" href="#_2-评估维度框架" aria-label="Permalink to &quot;2. 评估维度框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>问自己</th><th>怎么获取信息</th></tr></thead><tbody><tr><td><strong>业务前景</strong></td><td>这个业务 3 年后还在不在？是核心还是边缘？</td><td>面经、财报、行业报告</td></tr><tr><td><strong>技术栈</strong></td><td>这里的技术债多吗？技术氛围好吗？</td><td>面试时问团队技术栈和迁移规划</td></tr><tr><td><strong>团队氛围</strong></td><td>Code Review 怎么做的？有没有 Tech Debt 管理？</td><td>面试官和同事的沟通方式</td></tr><tr><td><strong>晋升空间</strong></td><td>这个职级的晋升周期和成功率？</td><td>问 HR 晋升数据，问面试官晋升经历</td></tr><tr><td><strong>稳定性</strong></td><td>最近有裁员吗？业务在增长还是收缩？</td><td>脉脉/一亩三分地/新闻</td></tr><tr><td><strong>总包</strong></td><td>总包构成是否合理？RSU 是否值得信任？</td><td>Levels.fyi/OfferShow</td></tr></tbody></table><h3 id="_3-面试时的反向问题-帮你了解公司" tabindex="-1">3. 面试时的反向问题（帮你了解公司） <a class="header-anchor" href="#_3-面试时的反向问题-帮你了解公司" aria-label="Permalink to &quot;3. 面试时的反向问题（帮你了解公司）&quot;">​</a></h3><p>这些问题是资深前端面试时<strong>必须问</strong>的，也是展示你思考深度的机会：</p><p><strong>🔴 必问（面试官环节）：</strong></p><ul><li>&quot;目前团队前端的技术栈是什么？有计划升级吗？&quot;</li><li>&quot;团队的 Code Review 流程是怎样的？&quot;</li><li>&quot;技术债务是怎么管理的？有没有专门的时间还债？&quot;</li><li>&quot;前端团队在组织里的位置是怎样的？和产品/后端怎么协作？&quot;</li></ul><p><strong>🟡 进阶（Tech Lead/HR 环节）：</strong></p><ul><li>&quot;前端团队的成长路径是怎样的？P6→P7 的关键差异是什么？&quot;</li><li>&quot;过去一年团队最大的技术挑战是什么？怎么解决的？&quot;</li><li>&quot;公司对 AI 辅助开发的策略是什么？&quot;</li><li>&quot;如果入职前三个月，你希望我优先解决什么问题？&quot;</li></ul><p><strong>🔵 必问（HR 环节）：</strong></p><ul><li>&quot;这个岗位是新开的还是有人离职？&quot;</li><li>&quot;团队有多少人？前端和后端的比例？&quot;</li><li>&quot;绩效考核是怎么做的？360 环评还是 OKR？&quot;</li><li>&quot;公司的晋升周期和成功率？&quot;</li></ul><h3 id="_4-不同目标的最佳选择" tabindex="-1">4. 不同目标的最佳选择 <a class="header-anchor" href="#_4-不同目标的最佳选择" aria-label="Permalink to &quot;4. 不同目标的最佳选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你的目标</th><th>推荐选择</th></tr></thead><tbody><tr><td>快速提升技术深度</td><td>大厂核心业务线 / 技术驱动型中厂</td></tr><tr><td>积累架构经验</td><td>中大型公司新建项目 / 技术转型期的大厂</td></tr><tr><td>追求 WLB</td><td>外企 / 部分成熟期互联网公司</td></tr><tr><td>最大化短期收入</td><td>字节/拼多多/外企</td></tr><tr><td>赌一把期权回报</td><td>C-D 轮独角兽 / 已盈利创业公司</td></tr><tr><td>技术广度 + 全栈能力</td><td>创业公司 / 前端团队小的中厂</td></tr><tr><td>品牌背书后跳槽</td><td>一线大厂核心部门</td></tr></tbody></table><h2 id="面试问法" tabindex="-1">面试问法 <a class="header-anchor" href="#面试问法" aria-label="Permalink to &quot;面试问法&quot;">​</a></h2><ul><li><p>🔥 <strong>怎么判断一家公司值不值得去？</strong></p><ul><li>核心原则：<strong>这段经历能不能让你 2 年后更值钱</strong></li><li>三个关键信号：团队里有比你强的人、业务在增长、你有足够的决策空间</li><li>警惕信号：团队全是新人、没有 Code Review、技术栈 3 年没变过、核心人员频繁离职</li></ul></li><li><p>⭐ <strong>Offer 比较时应该看什么？</strong></p><ul><li>总包差异 &lt;20% 时，优先看长期价值（成长速度、团队质量、业务前景）</li><li>总包差异 &gt;30% 时，除非有特别大的成长差异，否则选钱多的</li><li>不要为了&quot;大厂光环&quot;去一个边缘业务线——边缘业务 2 年 = 简历空白期</li></ul></li><li><p>⭐ <strong>被裁员后怎么选公司？</strong></p><ul><li>优先选择业务稳定的公司（不意味知名大厂）</li><li>不要因为急于上岸而接受明显降级的 Offer</li><li>可以考虑有政府/国企背景的科技公司作为过渡</li></ul></li></ul><h2 id="💡-ai-辅助学习" tabindex="-1">💡 AI 辅助学习 <a class="header-anchor" href="#💡-ai-辅助学习" aria-label="Permalink to &quot;💡 AI 辅助学习&quot;">​</a></h2><blockquote><p>用这个 Prompt 让 AI 帮你分析公司选择： &quot;你是一个有 10 年经验的前端架构师，现在帮我分析以下两个 Offer 的选择：</p><p>Offer A: [描述公司、业务、职级、总包、团队情况] Offer B: [同上]</p><p>我的背景：[当前工作经验、技术水平、职业目标]</p><p>请从以下几个维度进行分析：</p><ol><li>短期（1 年内）的成长机会</li><li>中期（2-3 年）的职业杠杆</li><li>长期（5 年）的天花板</li><li>如果选 A，3 年后是否容易跳去 B 类公司？反之呢？</li><li>你的最终建议和理由&quot;</li></ol></blockquote><h2 id="关联知识" tabindex="-1">关联知识 <a class="header-anchor" href="#关联知识" aria-label="Permalink to &quot;关联知识&quot;">​</a></h2><ul><li><a href="./salary-negotiation.html">谈薪策略</a> — 确定 Offer 后的谈判技巧</li><li><a href="./interview-flow.html">面试流程解析</a> — 面试全流程</li><li><a href="./foreign-company.html">外企面试专题</a> — 外企面试和选择</li><li><a href="./interview-mindset.html">面试心态与准备</a> — 面试全流程心理准备</li></ul>',32))])}const C=n(u,[["render",B]]);export{m as __pageData,C as default};
